package org.linguafree.core.domain.game

import org.linguafree.core.domain.model.LessonResult
import org.linguafree.core.domain.model.SessionKind
import org.linguafree.core.domain.model.Wallet

/**
 * Hearts: max 5, −1 per mistake in a lesson, +1 every 30 minutes.
 * At 0 hearts the learner can: (a) do a free practice that restores all hearts,
 * (b) wait. Hearts are never sold for gems. "Режим без сердец" switches hearts off entirely.
 */
object HeartsRules {
    const val MAX = 5
    const val REFILL_MS = 30 * 60 * 1000L

    /** Adds hearts that regenerated by [now]. */
    fun regenerate(wallet: Wallet, now: Long): Wallet {
        var hearts = wallet.hearts.coerceIn(0, MAX)
        var at = wallet.heartsRefillAt
        if (hearts >= MAX) return wallet.copy(hearts = MAX, heartsRefillAt = null)
        if (at == null) return wallet.copy(hearts = hearts, heartsRefillAt = now + REFILL_MS)
        while (hearts < MAX && at!! <= now) {
            hearts++
            at += REFILL_MS
        }
        return wallet.copy(hearts = hearts, heartsRefillAt = if (hearts >= MAX) null else at)
    }

    fun loseHeart(wallet: Wallet, now: Long): Wallet {
        val w = regenerate(wallet, now)
        if (w.hearts <= 0) return w
        val hearts = w.hearts - 1
        return w.copy(hearts = hearts, heartsRefillAt = w.heartsRefillAt ?: (now + REFILL_MS))
    }

    fun refillAll(wallet: Wallet) = wallet.copy(hearts = MAX, heartsRefillAt = null)

    /** Milliseconds until the next heart, or null when full. */
    fun msToNext(wallet: Wallet, now: Long): Long? = wallet.heartsRefillAt?.let { (it - now).coerceAtLeast(0) }

    /** Milliseconds until all hearts are back. */
    fun msToFull(wallet: Wallet, now: Long): Long? {
        val next = msToNext(wallet, now) ?: return null
        return next + (MAX - wallet.hearts - 1).coerceAtLeast(0) * REFILL_MS
    }
}

/** XP and gem rewards. Gems are earned only by learning; there is no way to buy them. */
object Rewards {
    const val LESSON_XP = 10
    const val PERFECT_BONUS_XP = 5
    const val SPEED_BONUS_XP = 5
    const val TEST_XP = 20
    const val LEGENDARY_XP = 30
    const val PRACTICE_XP = 10
    /** A lesson faster than this (12 exercises × ~10 s) earns the speed bonus. */
    const val FAST_LESSON_MS = 150_000L

    const val LESSON_GEMS = 5
    const val PERFECT_GEMS = 5
    const val TEST_GEMS = 15
    const val LEGENDARY_GEMS = 20
    val CHEST_GEMS = 15..30

    data class Reward(val baseXp: Int, val bonusXp: Int, val gems: Int) {
        val totalXp: Int get() = baseXp + bonusXp
    }

    fun forSession(kind: SessionKind, mistakes: Int, durationMs: Long, passed: Boolean, total: Int): Reward {
        if (!passed || total == 0) return Reward(0, 0, 0)
        val perfect = mistakes == 0
        val fast = durationMs in 1..FAST_LESSON_MS
        val base = when (kind) {
            SessionKind.Lesson, SessionKind.Story -> LESSON_XP
            SessionKind.UnitTest, SessionKind.SkipTest -> TEST_XP
            SessionKind.Legendary -> LEGENDARY_XP
            SessionKind.Placement -> 0
            else -> PRACTICE_XP
        }
        val bonus = if (kind == SessionKind.Placement) 0 else
            (if (perfect) PERFECT_BONUS_XP else 0) + (if (fast && kind.spendsHearts) SPEED_BONUS_XP else 0)
        val gems = when (kind) {
            SessionKind.Lesson, SessionKind.Story -> LESSON_GEMS + if (perfect) PERFECT_GEMS else 0
            SessionKind.UnitTest, SessionKind.SkipTest -> TEST_GEMS
            SessionKind.Legendary -> LEGENDARY_GEMS
            SessionKind.Placement -> 0
            else -> 2
        }
        return Reward(base, bonus, gems)
    }

    /** Deterministic chest reward so re-opening after reinstall/import gives the same amount. */
    fun chestGems(nodeId: String): Int {
        val span = CHEST_GEMS.last - CHEST_GEMS.first + 1
        return CHEST_GEMS.first + Math.floorMod(nodeId.hashCode(), span)
    }

    fun todayXp(results: List<LessonResult>, dayStart: Long, dayEnd: Long) =
        results.filter { it.finishedAt in dayStart until dayEnd }.sumOf { it.xp }
}

/** Items in the gem shop: streak freezes, fox outfits and themes. No real-money prices exist anywhere. */
enum class ShopItem(val title: String, val description: String, val price: Int) {
    StreakFreeze("Заморозка серии", "Спасёт серию, если пропустишь день. Можно держать до 2.", 100),
    OutfitScarf("Наряд: шарф", "Уютный полосатый шарф для лисёнка.", 150),
    OutfitCap("Наряд: кепка", "Кепка исследователя.", 200),
    OutfitBow("Наряд: бантик", "Нарядный бантик.", 150),
    OutfitCrown("Наряд: корона", "Для настоящих чемпионов.", 400),
    ThemeOcean("Тема «Океан»", "Голубая тема оформления.", 200),
    ThemeSunset("Тема «Закат»", "Тёплая оранжевая тема оформления.", 200),
    ThemeLilac("Тема «Сирень»", "Сиреневая тема оформления.", 200);

    val isCosmetic: Boolean get() = name.startsWith("Outfit") || name.startsWith("Theme")
}
